ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Responsavel_pelo_Custo__c, ''),
        $Profile.Name = 'Admin'
    ),
    AND(
        ISPICKVAL(Responsavel_pelo_Custo__c, ''),
        OR(
            ISPICKVAL(Status_de_Aprovacao__c, 'Aprovado'),
            ISPICKVAL(Status_de_Aprovacao__c, 'Pendente - Diretor comercial')
        )
    )
)
